// Homologar acesso privado, credenciais e deploy da migration 033 antes de permitir processamento.
const ENABLED = false;
return ENABLED ? $input.all() : [];

const tasks = $input.first()?.json?.items;
if (!Array.isArray(tasks) || tasks.length > 10) throw new Error('Contrato de tarefas nao confirmado.');
return tasks.map(task => {
  if (typeof task.claim_id !== 'string' || typeof task.text !== 'string'
    || !['instagram','waha'].includes(task.origin)
    || !Number.isSafeInteger(task.message_id)) throw new Error('Tarefa invalida.');
  return {json:{claim_id:task.claim_id,text:task.text},pairedItem:{item:0}};
});

const task = $('Individualizar classificacoes').item.json;
const raw = $json.output;
if (typeof raw !== 'string' || raw.length > 4096) throw new Error('Saida de IA invalida.');
let data;
try { data = JSON.parse(raw); } catch { throw new Error('Classificacao nao retornou JSON estrito.'); }
if (!data || typeof data !== 'object' || Array.isArray(data)
  || !['positive','negative','neutral','uncertain'].includes(data.sentiment)
  || !['low','medium','high'].includes(data.confidence)
  || typeof data.explanation !== 'string' || data.explanation.length > 250) {
  throw new Error('Contrato de sentimento invalido.');
}
return {json:{
  claim_id:task.claim_id,
  sentiment:data.sentiment,
  confidence:data.confidence,
  explanation:data.explanation
}};
